// newWALFixture writes a WAL-mode archive with two resource rows and returns
// its path. The writer connection is closed, which checkpoints and removes the
// sidecars, so a test that wants uncheckpointed frames opens its own writer.
func newWALFixture(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "data.db")
	db, err := sql.Open("sqlite", path+"?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatalf("opening fixture writer: %v", err)
	}
	defer db.Close() //nolint:errcheck // fixture
	stmts := []string{
		`CREATE TABLE resources (id TEXT NOT NULL, resource_type TEXT NOT NULL, data JSON NOT NULL,
			synced_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (resource_type, id))`,
		`INSERT INTO resources (id, resource_type, data) VALUES ('2026-01-01','steps','{"totalSteps":1200}')`,
		`INSERT INTO resources (id, resource_type, data) VALUES ('2026-01-02','steps','{"totalSteps":3400}')`,
	}
	for _, stmt := range stmts {
		if _, err := db.Exec(stmt); err != nil {
			t.Fatalf("seeding fixture (%s): %v", stmt, err)
		}
	}
	var mode string
	if err := db.QueryRow(`PRAGMA journal_mode`).Scan(&mode); err != nil {
		t.Fatalf("reading journal_mode: %v", err)
	}
	if mode != "wal" {
		t.Fatalf("fixture journal_mode = %q, want wal", mode)
	}
	return path
}

// archiveDigest is the fingerprint the blast-radius cases compare. It covers
// the database file and the WAL, which together are the archive's content.
// The -shm file is deliberately excluded: it is multi-process coordination
// state that a read-only open legitimately creates.
type archiveDigest struct {
	db      string
	walSize int64
	sidecar []string
}

func digestArchive(t *testing.T, path string) archiveDigest {
	t.Helper()
	raw, err := os.ReadFile(path) // #nosec G304 -- test fixture path
	if err != nil {
		t.Fatalf("reading %s: %v", path, err)
	}
	sum := sha256.Sum256(raw)
	d := archiveDigest{db: hex.EncodeToString(sum[:])}
	// A read-only open legitimately creates an empty -wal beside the file, so
	// "absent" and "present but zero bytes" are the same state: no committed
	// frames the main file does not already hold.
	if info, err := os.Stat(path + "-wal"); err == nil {
		d.walSize = info.Size()
	}
	entries, err := os.ReadDir(filepath.Dir(path))
	if err != nil {
		t.Fatalf("listing %s: %v", filepath.Dir(path), err)
	}
	for _, e := range entries {
		name := e.Name()
		if name == filepath.Base(path) || strings.HasSuffix(name, "-shm") || strings.HasSuffix(name, "-wal") {
			continue
		}
		d.sidecar = append(d.sidecar, name)
	}
	return d
}

func (d archiveDigest) equal(other archiveDigest) bool {
	if d.db != other.db || d.walSize != other.walSize || len(d.sidecar) != len(other.sidecar) {
		return false
	}
	for i := range d.sidecar {
		if d.sidecar[i] != other.sidecar[i] {
			return false
		}
	}
	return true
}

// runSQLCommand runs the verb the way a caller does, through Cobra, so flag
// wiring and the output pipeline are exercised rather than bypassed.
func runSQLCommand(t *testing.T, dbPath string, args ...string) (string, string, error) {
	t.Helper()
	return runSQLCommandWithFlags(t, &rootFlags{asJSON: true}, dbPath, args...)
}

// runSQLCommandWithFlags is runSQLCommand with the root flags a real
// invocation would have carried down. The root command parses --json/--select
// and friends as persistent flags (root.go), so a test that wants those set
// sets them here rather than passing words the subcommand cannot parse.
func runSQLCommandWithFlags(t *testing.T, flags *rootFlags, dbPath string, args ...string) (string, string, error) {
	t.Helper()
	cmd := newGarminSQLCmd(flags)
	var out, errOut bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errOut)
	cmd.SetContext(context.Background())
	cmd.SilenceUsage = true
	cmd.SetArgs(append([]string{"--db", dbPath}, args...))
	err := cmd.Execute()
	return out.String(), errOut.String(), err
}

func decodeSQLResult(t *testing.T, raw string) garminSQLResult {
	t.Helper()
	var result garminSQLResult
	if err := json.Unmarshal([]byte(raw), &result); err != nil {
		t.Fatalf("decoding result %q: %v", raw, err)
	}
	return result
}

// ---------------------------------------------------------------------------
// Blast radius
// ---------------------------------------------------------------------------

// TestGarminSQLBlastRadius is the reason this command is hand-written rather
// than a prefix check over a read-write handle. Every write form below was
// demonstrated to get through such a check in another printed CLI; here each
// one must be refused with the bytes on disk unchanged.
func TestGarminSQLBlastRadius(t *testing.T) {
	cases := []struct {
		name    string
		query   string
		allowed bool
	}{
		{"cte-insert", `WITH x AS (SELECT 1) INSERT INTO resources (id, resource_type, data) SELECT 'x','steps','{}'`, false},
		{"replace", `REPLACE INTO resources (id, resource_type, data) VALUES ('2026-01-01','steps','{"totalSteps":0}')`, false},
		{"attach", `ATTACH DATABASE 'SCRATCH/side.db' AS side`, false},
		{"vacuum-into", `VACUUM INTO 'SCRATCH/vacuum.db'`, false},
		{"pragma-journal-mode", `PRAGMA journal_mode=DELETE`, false},
		{"second-statement", `SELECT 1; DROP TABLE resources`, false},
		{"leading-comment-drop", "-- harmless\nDROP TABLE resources", false},
		{"block-comment-drop", `/* harmless */ DROP TABLE resources`, false},
		{"writefile", `SELECT writefile('SCRATCH/exfil.txt', data) FROM resources`, false},
		{"load-extension", `SELECT load_extension('SCRATCH/evil.dylib')`, false},
		{"plain-select", `SELECT id, resource_type FROM resources ORDER BY id`, true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dbPath := newWALFixture(t)
			scratch := t.TempDir()
			query := strings.ReplaceAll(tc.query, "SCRATCH", scratch)

			before := digestArchive(t, dbPath)
			// "--" so Cobra's flag parser hands a query that starts with a
			// SQL line comment straight through to the gate rather than
			// refusing it as an unknown flag. The gate is what is under test.
			out, _, err := runSQLCommand(t, dbPath, "--", query)
			after := digestArchive(t, dbPath)

			if !after.equal(before) {
				t.Fatalf("archive changed: before=%+v after=%+v", before, after)
			}
			if entries, readErr := os.ReadDir(scratch); readErr != nil {
				t.Fatalf("listing scratch: %v", readErr)
			} else if len(entries) != 0 {
				names := make([]string, 0, len(entries))
				for _, e := range entries {
					names = append(names, e.Name())
				}
				t.Fatalf("%s wrote files outside the archive: %v", tc.name, names)
			}

			if tc.allowed {
				if err != nil {
					t.Fatalf("plain SELECT was refused: %v", err)
				}
				result := decodeSQLResult(t, out)
				if result.Count != 2 {
					t.Fatalf("plain SELECT returned %d rows, want 2: %s", result.Count, out)
				}
				return
			}
			if err == nil {
				t.Fatalf("%s was accepted; output: %s", tc.name, out)
			}
			if strings.TrimSpace(err.Error()) == "" {
				t.Fatalf("%s was refused with an empty message", tc.name)
			}
		})
	}
}

// TestGarminSQLGuardMessagesAreActionable pins the refusal wording. A gate
// that refuses without saying what it wants teaches nothing.
func TestGarminSQLGuardMessagesAreActionable(t *testing.T) {
	dbPath := newWALFixture(t)
	for _, tc := range []struct{ name, query, want string }{
		{"multi-statement", `SELECT 1; DROP TABLE resources`, "only a single SELECT or WITH statement is allowed"},
		{"non-select", `DROP TABLE resources`, "only SELECT queries are allowed"},
		{"line-comment", "-- harmless\nDROP TABLE resources", "only SELECT queries are allowed"},
		{"block-comment", `/* harmless */ DROP TABLE resources`, "only SELECT queries are allowed"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, _, err := runSQLCommand(t, dbPath, "--", tc.query)
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %v, want it to contain %q", err, tc.want)
			}
		})
	}
}

// TestGarminSQLHandleRefusesWritesWithoutTheGate proves the second layer on
// its own: the same write forms are refused by the handle even when the
// statement gate is bypassed entirely. Without this, a future change to the
// gate could silently become the only thing standing between a query and the
// archive.
func TestGarminSQLHandleRefusesWritesWithoutTheGate(t *testing.T) {
	dbPath := newWALFixture(t)
	db, err := openGarminArchiveReadOnly(context.Background(), dbPath)
	if err != nil {
		t.Fatalf("opening read-only handle: %v", err)
	}
	defer db.Close() //nolint:errcheck // test handle

	before := digestArchive(t, dbPath)
	for _, query := range []string{
		`WITH x AS (SELECT 1) INSERT INTO resources (id, resource_type, data) SELECT 'x','steps','{}'`,
		`REPLACE INTO resources (id, resource_type, data) VALUES ('2026-01-01','steps','{}')`,
		`DROP TABLE resources`,
		`UPDATE resources SET data = '{}'`,
		`DELETE FROM resources`,
	} {
		if _, err := db.ExecContext(context.Background(), query); err == nil {
			t.Fatalf("read-only handle accepted %q", query)
		}
	}
	if after := digestArchive(t, dbPath); !after.equal(before) {
		t.Fatalf("archive changed under direct writes: before=%+v after=%+v", before, after)
	}

	var queryOnly string
	if err := db.QueryRow(`PRAGMA query_only`).Scan(&queryOnly); err != nil {
		t.Fatalf("reading query_only: %v", err)
	}
	if queryOnly != "1" {
		t.Fatalf("query_only = %q on the verb's handle, want 1", queryOnly)
	}
}

// ---------------------------------------------------------------------------
// WAL visibility
// ---------------------------------------------------------------------------

// TestGarminSQLSeesUncheckpointedWALCommit is the test that decided the open
// mode. store.OpenReadOnly once opened mode=ro&immutable=1, which tells SQLite
// there is no WAL to consult; against a live archive that is false, and the
// store now opens mode=ro with query_only instead. This asserts both halves:
// the verb sees the row, and an immutable handle to the same file does not —
// so the difference is the flag, not the fixture.
func TestGarminSQLSeesUncheckpointedWALCommit(t *testing.T) {
	dbPath := newWALFixture(t)

	writer, err := sql.Open("sqlite", dbPath+"?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatalf("opening writer: %v", err)
	}
	writer.SetMaxOpenConns(1)
	defer writer.Close() //nolint:errcheck // test writer
	if _, err := writer.Exec(`INSERT INTO resources (id, resource_type, data) VALUES ('2026-01-03','steps','{"totalSteps":5600}')`); err != nil {
		t.Fatalf("committing third row: %v", err)
	}
	// The writer connection stays open, so nothing checkpoints the frame.
	info, err := os.Stat(dbPath + "-wal")
	if err != nil {
		t.Fatalf("stat -wal: %v", err)
	}
	if info.Size() == 0 {
		t.Fatalf("-wal is empty; the commit was already checkpointed and this test would prove nothing")
	}

	out, _, err := runSQLCommand(t, dbPath, `SELECT count(*) AS n FROM resources`)
	if err != nil {
		t.Fatalf("sql verb failed: %v", err)
	}
	result := decodeSQLResult(t, out)
	if len(result.Rows) != 1 {
		t.Fatalf("expected one row, got %s", out)
	}
	if got := fmt.Sprint(result.Rows[0]["n"]); got != "3" {
		t.Fatalf("verb saw %s rows, want 3 — the uncheckpointed commit is invisible", got)
	}

	immutable, err := sql.Open("sqlite", "file:"+dbPath+"?mode=ro&immutable=1&_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatalf("opening immutable handle: %v", err)
	}
	defer immutable.Close() //nolint:errcheck // comparison handle
	var n int
	if err := immutable.QueryRow(`SELECT count(*) FROM resources`).Scan(&n); err != nil {
		// A schema that is invisible is the same finding as a row that is:
		// immutable=1 does not see this archive.
		return
	}
	if n == 3 {
		t.Fatalf("immutable=1 saw the uncheckpointed commit; the reason this verb drops the flag no longer holds")
	}
}

