// TestGarminSQLRefusesAFlagAfterTheQuery pins the one shape that used to be
// silent. Everything after the documented bare -- is a positional, so a flag
// written there was joined onto the query and parsed by SQLite as a line
// comment: the query ran, the flag was dropped and the exit code was 0.
func TestGarminSQLRefusesAFlagAfterTheQuery(t *testing.T) {
	dbPath := newWALFixture(t)
	for _, flag := range []string{"--agent", "--quiet"} {
		t.Run(flag, func(t *testing.T) {
			out, _, err := runSQLCommand(t, dbPath, "--", "SELECT count(*) AS n FROM resources", flag)
			if err == nil {
				t.Fatalf("%s after the query was accepted; output: %s", flag, out)
			}
			if !strings.Contains(err.Error(), flag) || !strings.Contains(err.Error(), "before the bare --") {
				t.Fatalf("refusal does not name the flag and the rule: %v", err)
			}
		})
	}
}

